from __future__ import annotations
import math

def transformed_gap(p: int, q: int) -> float:
    return abs(1.0 / math.log(p) - 1.0 / math.log(q))

def twin_approximation(p: int) -> float:
    return 2.0 / (p * math.log(p) ** 2)

if __name__ == "__main__":
    for p in (11, 101, 10007, 1000037):
        q = p + 2
        exact = transformed_gap(p, q)
        print(p, exact, twin_approximation(p), exact / twin_approximation(p))

from __future__ import annotations
import math

def asymptotic_ratio(sample_size: int, epsilons: list[float]) -> list[float]:
    return [math.log(sample_size) / math.log(1.0 / e) for e in epsilons]

if __name__ == "__main__":
    scales = [10.0 ** (-k) for k in range(2, 15, 2)]
    for e, ratio in zip(scales, asymptotic_ratio(1000, scales)):
        print(f"epsilon={e:.0e}, ratio={ratio:.6f}")

