from __future__ import annotations
import math

def primes_up_to(limit: int) -> list[int]:
    if limit < 2:
        return []
    sieve = bytearray(b"\x01") * (limit + 1)
    sieve[0:2] = b"\x00\x00"
    for p in range(2, math.isqrt(limit) + 1):
        if sieve[p]:
            sieve[p*p:limit+1:p] = b"\x00" * (((limit-p*p)//p)+1)
    return [n for n, flag in enumerate(sieve) if flag]

def coordinates(limit: int) -> list[float]:
    return [1.0 / math.log(p) for p in primes_up_to(limit)]

if __name__ == "__main__":
    ps = primes_up_to(100_000)
    xs = coordinates(100_000)
    print(f"{len(ps)} primes; coordinate range {min(xs):.8g} to {max(xs):.8g}")

from __future__ import annotations
import math
from typing import Sequence

def minimum_interval_cover(points: Sequence[float], epsilon: float) -> int:
    if epsilon <= 0:
        raise ValueError("epsilon must be positive")
    xs = sorted(points)
    count = i = 0
    while i < len(xs):
        right = xs[i] + epsilon
        count += 1
        i += 1
        while i < len(xs) and xs[i] <= right:
            i += 1
    return count

if __name__ == "__main__":
    sample = [0.0, 0.01, 0.04, 0.11, 0.12, 0.3]
    for eps in (0.2, 0.1, 0.05, 0.01):
        print(eps, minimum_interval_cover(sample, eps))

from __future__ import annotations

def covering_certificate(n: int, s: float, delta: float) -> tuple[list[float], float]:
    if n < 0 or s <= 0 or delta <= 0:
        raise ValueError("require n >= 0, s > 0, delta > 0")
    diameters = [delta * 2.0 ** (-(k + 1) / s) for k in range(n)]
    return diameters, sum(d ** s for d in diameters)

if __name__ == "__main__":
    for s in (0.5, 1.0, 2.0):
        _, cost = covering_certificate(1000, s, 1e-4)
        print(f"s={s}: total cost={cost:.8g}")

