from __future__ import annotations
import math

def write_svg(path: str = "prime_coordinates.svg", limit: int = 200) -> None:
    def prime(n: int) -> bool:
        return n >= 2 and all(n % d for d in range(2, math.isqrt(n) + 1))
    xs = [1 / math.log(p) for p in range(2, limit + 1) if prime(p)]
    lo, hi = min(xs), max(xs)
    dots = "".join(f'<circle cx="{40+720*(x-lo)/(hi-lo):.2f}" cy="80" r="3" fill="#6d28d9"/>' for x in xs)
    svg=f'<svg xmlns="http://www.w3.org/2000/svg" width="800" height="160"><rect width="100%" height="100%" fill="#fafafa"/><line x1="40" y1="80" x2="760" y2="80" stroke="#111"/>{dots}<text x="40" y="130" font-family="sans-serif">Logarithmic prime coordinates for p ≤ {limit}</text></svg>'
    open(path,"w",encoding="utf-8").write(svg)
if __name__ == "__main__": write_svg()

